<script setup lang="ts">
import {useTaskGuard} from './taskGuard'
import { computed, nextTick, onUnmounted, ref, shallowRef, watch } from 'vue'
import { fetchDetail, savedPointRows, detailFinalLabel, decisionLabel, type Detail } from './records'
import { pointKey, savedChoices, resolvedChoice, unresolved, confirmationAllowed, reviewable, confirmTeacher, recordReview, confirmBlank, originalUrl, type Choices } from './teacherReview'
import SubmissionDetail from './SubmissionDetail.vue'
const props=defineProps<{id:string;expectedExamId?:string}>()
const emit=defineEmits<{saved:[detail:Detail];confirmed:[detail:Detail]}>()
const data=shallowRef<Detail>(),choices=ref<Choices>({}),busy=ref(false),error=ref(''),message=ref(''),note=ref(''),editing=ref(false),uncertain=ref(false),seen=ref<number[]>([]),opened=ref<number[]>([]),originalChecked=ref(false),expanded=ref(false),blank=ref<Record<string,boolean>>({}),version=ref(0)
useTaskGuard(computed(()=>busy.value||!!(data.value&&editing.value&&(JSON.stringify(choices.value)!==JSON.stringify(savedChoices(data.value))||note.value!==((data.value.result.dual_review?.teacher_final||data.value.result.teacher_final)?.teacher_note||'')))))
const reviewRoot=ref<HTMLElement>()
let firstRead=true
let revision=0,alive=true
const rows=computed(()=>data.value?savedPointRows(data.value).sort((a,b)=>Number(b.aDecision!==b.bDecision||b.aScore!==b.bScore)-Number(a.aDecision!==a.bDecision||a.aScore!==a.bScore)):[])
const pending=computed(()=>rows.value.filter(r=>!['full','none'].includes(resolvedChoice(choices.value[pointKey(r.questionId,r.pointId)]||'',r)||'')))
const dirty=computed(()=>!!data.value&&(JSON.stringify(choices.value)!==JSON.stringify(savedChoices(data.value))||note.value!==((data.value.result.dual_review?.teacher_final||data.value.result.teacher_final)?.teacher_note||'')))
function focusPending(){const r=pending.value[0];if(r){const el=document.getElementById('teacher-'+r.questionId+'-'+r.pointId);el?.focus();el?.scrollIntoView({block:'center'})}}
const canConfirm=computed(()=>!!data.value&&confirmationAllowed(data.value,choices.value)&&editing.value&&!busy.value&&!uncertain.value)
function assertExam(d:Detail){if(props.expectedExamId&&d.exam_id!==props.expectedExamId)throw new Error('答卷不属于当前考试，已阻止终评写入')}
function hydrate(d:Detail){assertExam(d);data.value=d;choices.value=savedChoices(d);note.value=(d.result.dual_review?.teacher_final||d.result.teacher_final)?.teacher_note||'';editing.value=!d.confirmed_at||!!d.teacher_reconfirmation_required;seen.value=[];opened.value=[];originalChecked.value=false;blank.value={};expanded.value=false;version.value++}
async function reload(){const token=++revision;busy.value=true;data.value=undefined;error.value='';uncertain.value=false;try{const d=await fetchDetail(props.id);if(alive&&token===revision){hydrate(d);if(firstRead){firstRead=false;await nextTick();reviewRoot.value?.scrollIntoView({block:'start'});reviewRoot.value?.focus({preventScroll:true})}}}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{if(alive&&token===revision)busy.value=false}}
async function write(action:()=>Promise<unknown>,success:string,preserveDraft=false){if(busy.value||uncertain.value)return;const token=revision;busy.value=true;error.value='';message.value='';try{await action();if(!alive||token!==revision)return;const d=await fetchDetail(props.id);if(!alive||token!==revision)return;if(preserveDraft&&data.value?.id===d.id){data.value=d;blank.value={};version.value++}else hydrate(d);message.value=success;emit('saved',d);return d}catch{if(alive&&token===revision){uncertain.value=true;error.value='操作未能确认。请先重新读取服务器记录再决定下一步；不会自动重试或重复保存。'}}finally{if(alive&&token===revision)busy.value=false}}
async function save(){if(!canConfirm.value||!data.value)return;const d=data.value;assertExam(d);const saved=await write(()=>confirmTeacher(d,choices.value,note.value,expanded.value),'教师终评已保存，总分由服务器按逐点判断确定性计算。');if(saved?.confirmed_at&&!saved.teacher_reconfirmation_required)emit('confirmed',saved)}
function review(){if(!data.value||!originalChecked.value||!seen.value.length||!reviewable(data.value))return;return write(()=>recordReview(props.id,note.value),'已保存原图人工复核记录。',true)}
function chooseConfirmedBlanks(){if(!data.value||busy.value||uncertain.value||!editing.value)return;const ids=new Set((data.value.result.sub_questions||[]).filter(q=>q.answer_status==='blank_confirmed').map(q=>q.sub_question_id));for(const r of rows.value)if(ids.has(r.questionId))choices.value[pointKey(r.questionId,r.pointId)]='teacher_none'}
function markBlank(q:string){if(!blank.value[q])return;return write(()=>confirmBlank(props.id,q),'已保存该小题空白确认；请继续完成逐点终评。',true)}
watch(()=>props.id,()=>{firstRead=true;message.value='';reload()},{immediate:true})
onUnmounted(()=>{alive=false;revision++;data.value=undefined;choices.value={};seen.value=[];opened.value=[];note.value=''})
</script>
<template><section ref="reviewRoot" tabindex="-1" class="teacher-review" aria-label="教师逐点终评"><h3>教师逐点终评</h3><p>逐点判断决定最终成绩；总分由服务端计算，此页不能手填总分。保存不会重新调用模型。</p>
 <button @click="reload" :disabled="busy">重新读取服务器记录</button><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <template v-if="data"><p v-if="data.result.photos_discarded_unconfirmed" role="alert">此份未终评答卷的照片已弃用清理，需重新上传后才能核对原图并保存终评。</p><p class="muted review-paper">当前答卷：{{data.marking_code||'答卷 '+data.id.slice(0,6)}}</p><p v-if="unresolved(data)||(data.result.blocked&&!data.manual_reviewed)" role="alert">尚不能保存正式终评：请核对原图，并处理未确认空白、题号或阻断问题。{{data.result.block_reasons?.join('；')}}</p><div class="review-status"><span class="status-tag" :class="dirty?'warning':data.confirmed_at&&!data.teacher_reconfirmation_required?'success':'neutral'">{{dirty?'尚未保存':data.teacher_reconfirmation_required?'待重新确认':data.confirmed_at?'已保存':'待教师终评'}}</span><p>服务器终评：<strong data-testid="teacher-server-total">{{ detailFinalLabel(data) }}</strong></p><span>{{rows.length-pending.length}} / {{rows.length}}个评分点在当前选择中已有明确判断</span><button v-if="pending.length&&editing" class="secondary" @click="focusPending">定位下一未判断评分点</button></div>
  <p v-if="data.confirmation_method==='teacher_batch_adoption'">当前成绩来自教师批量采纳 AI 共识，未逐点评阅。可点击重新逐点改判；保存后以本次教师终评为准。</p>
  <details class="review-summary"><summary>查看完整 AI 双评记录与证据</summary><SubmissionDetail :id="id" :key="id+':'+version" in-teacher-review /></details>
  <div class="review-grid"><div class="review-original"><details @toggle="expanded=($event.target as HTMLDetailsElement).open"><summary>查看完整题目与参考答案</summary><article v-for="q in data.teacher_scoring_questions" :key="q.id"><h4>{{ q.label||q.id }}</h4><p>{{ q.question }}</p><p>{{ q.standard_answer }}</p></article></details>
  <section><h4>原图与人工复核</h4><p>点击查看才会请求原图并产生既有服务端查看回执；看到图片不等于已完成核对。</p><p v-if="!data.photos?.length">原图不存在或未保存；不伪造查看回执。</p>
   <div v-for="(_,i) in data.photos" :key="i"><button :disabled="busy" @click="opened.includes(i)||opened.push(i)">查看原图第{{ i+1 }}张</button><a v-if="opened.includes(i)" class="image-enlarge" :href="originalUrl(id,i+1)" target="_blank" rel="noopener">放大查看原图第{{i+1}}张</a><img v-if="opened.includes(i)" class="upload-preview" :src="originalUrl(id,i+1)" :alt="'原图第'+(i+1)+'张'" @load="seen.includes(i)||seen.push(i)" @error="error='原图未能读取，请勿确认已查看。'"></div>
   <label class="check"><input type="checkbox" v-model="originalChecked" :disabled="busy||!seen.length">我已打开原图并核对模型证据</label><button @click="review" :disabled="busy||uncertain||!originalChecked||!seen.length||!reviewable(data)">记录人工复核</button>
  </section></div><div class="review-decisions">
  <template v-for="q in data.result.sub_questions" :key="q.sub_question_id"><div v-if="q.answer_status==='unanswered_candidate'" class="point-record"><label class="check"><input type="checkbox" v-model="blank[q.sub_question_id]" :disabled="busy||uncertain">我已核对原图，确认{{ q.sub_question_id }}确实未作答</label><button @click="markBlank(q.sub_question_id)" :disabled="busy||uncertain||!blank[q.sub_question_id]">确认{{ q.sub_question_id }}为空白</button></div></template>
  <button v-if="!editing" :disabled="busy||uncertain" @click="editing=true">重新逐点改判（保存后留审计记录）</button>
  <fieldset :disabled="busy||uncertain||!editing"><legend>本次教师判断</legend><button v-if="data.result.sub_questions?.some(q=>q.answer_status==='blank_confirmed')" @click="chooseConfirmedBlanks">已确认空白题的评分点全部选为不给分</button><p>模型判断或分数不同的评分点优先排列；其余评分点仍可核对和改判。</p>
   <p v-if="!rows.length">没有可确认的服务端评分点，不能保存终评。</p>
   <div v-for="r in rows" :key="pointKey(r.questionId,r.pointId)" class="point-record teacher-point" :class="{pending:pending.some(p=>p.questionId===r.questionId&&p.pointId===r.pointId)}"><span class="status-tag neutral">{{pending.some(p=>p.questionId===r.questionId&&p.pointId===r.pointId)?'待判断':'已判断'}}</span><label :for="'teacher-'+r.questionId+'-'+r.pointId">{{ r.questionId }} / {{ r.pointId }} · {{ r.label }}（{{ r.maximum }}分）</label><div class="point-evidence"><p><strong>AI-A：{{decisionLabel(r.aDecision)}}</strong> · {{r.aEvidence||'未提供引文'}}</p><p><strong>AI-B：{{decisionLabel(r.bDecision)}}</strong> · {{r.bEvidence||'未提供引文'}}</p></div><select :id="'teacher-'+r.questionId+'-'+r.pointId" :value="choices[pointKey(r.questionId,r.pointId)]||''" @change="choices[pointKey(r.questionId,r.pointId)]=($event.target as HTMLSelectElement).value"><option value="">未判断</option><option value="teacher_full">教师给分</option><option value="teacher_none">教师不给分</option><option value="teacher_uncertain">不确定，暂不确认</option><option v-if="r.aDecision" value="model_a">采用AI-A当前判断</option><option v-if="r.bDecision" value="model_b">采用AI-B当前判断</option></select></div>
   <label>教师备注<textarea v-model="note" maxlength="2000"></textarea></label><p>只有所有评分点均已确定给分/不给分且通过既有门禁时才能保存；不确定、未确认空白或未对应题号不能确认。</p><div class="review-savebar"><span>{{pending.length?'还有'+pending.length+'个评分点待判断':'评分点已判断，保存仍需通过全部终评门禁'}}</span><button class="primary" @click="save" :disabled="!canConfirm">保存教师终评</button></div>
  </fieldset></div></div>
 </template>
</section></template>
